    private static Font escolherFonte(String[] preferencias, Float peso){
        Font[] instaladas=GraphicsEnvironment.getLocalGraphicsEnvironment().getAllFonts();
        for(String nome:preferencias){
            for(Font f:instaladas){
                if(f.getFontName(Locale.ENGLISH).equalsIgnoreCase(nome)||f.getPSName().equalsIgnoreCase(nome))return f;
            }
        }
        return new Font(Font.SANS_SERIF,Font.PLAIN,12).deriveFont(Map.of(java.awt.font.TextAttribute.WEIGHT,peso));
    }
    static Font fonte(int tamanho){return (tamanho>=25?TITULO_FINO:TEXTO_LEVE).deriveFont((float)tamanho);}
    private static JLabel label(String s,int size){JLabel l=new JLabel(s);l.setFont(fonte(size));l.setForeground(INK);return l;}
