    private static JScrollPane rolagem(Component c){JScrollPane s=new JScrollPane(c);s.setOpaque(false);s.getViewport().setOpaque(false);s.setBorder(null);s.setViewportBorder(null);s.getVerticalScrollBar().setUnitIncrement(24);for(JScrollBar bar:new JScrollBar[]{s.getVerticalScrollBar(),s.getHorizontalScrollBar()}){bar.setOpaque(false);bar.setUI(new BarraSuave());}SwingUtilities.invokeLater(()->{s.setBorder(null);if(s.getColumnHeader()!=null)s.getColumnHeader().setOpaque(false);});return s;}
    private static class BarraSuave extends javax.swing.plaf.basic.BasicScrollBarUI {
        protected JButton createDecreaseButton(int o){return invisivel();}protected JButton createIncreaseButton(int o){return invisivel();}
        private JButton invisivel(){JButton b=new JButton();b.setPreferredSize(new Dimension(0,0));b.setMinimumSize(new Dimension(0,0));b.setMaximumSize(new Dimension(0,0));return b;}
        public Dimension getPreferredSize(JComponent c){return new Dimension(10,10);}
        protected void paintTrack(Graphics g,JComponent c,Rectangle r){}
        protected void paintThumb(Graphics gg,JComponent c,Rectangle r){if(r.isEmpty()||!scrollbar.isEnabled())return;Graphics2D g=(Graphics2D)gg.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(new Color(48,74,84,isThumbRollover()?155:95));g.fillRoundRect(r.x+2,r.y+2,Math.max(1,r.width-4),Math.max(1,r.height-4),6,6);g.dispose();}
    }
    private static class BotaoSuave extends JButton {
        boolean ativo; float brilho; final javax.swing.Timer timer;
        BotaoSuave(String texto){super(texto);setOpaque(false);setContentAreaFilled(false);setFocusPainted(false);timer=new javax.swing.Timer(16,e->{float alvo=getModel().isRollover()?1:0;brilho+=(alvo-brilho)*.23f;repaint();if(Math.abs(alvo-brilho)<.01){brilho=alvo;((javax.swing.Timer)e.getSource()).stop();}});getModel().addChangeListener(e->{if(!timer.isRunning())timer.start();});}
        protected void paintComponent(Graphics gg){Graphics2D g=(Graphics2D)gg.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);if(ativo){g.setPaint(new GradientPaint(0,0,new Color(255,255,255,0),getWidth(),0,new Color(36,58,68,105)));g.fillRect(0,0,getWidth(),getHeight());g.setColor(new Color(235,246,247,200));g.fillRect(getWidth()-2,7,2,getHeight()-14);}if(brilho>0){g.setColor(new Color(255,255,255,(int)(58*brilho)));g.fillRect(0,0,getWidth(),getHeight());}if(isFocusOwner()){g.setColor(new Color(56,88,99,150));g.drawLine(9,getHeight()-3,getWidth()-9,getHeight()-3);}g.dispose();super.paintComponent(gg);}
    }
    private static class Transicao extends JPanel {
        float fase=1; long inicio; final javax.swing.Timer timer;
        Transicao(LayoutManager l){super(l);timer=new javax.swing.Timer(16,e->{fase=Math.min(1,(System.nanoTime()-inicio)/280_000_000f);repaint();if(fase>=1)((javax.swing.Timer)e.getSource()).stop();});}
        void animar(){fase=0;inicio=System.nanoTime();timer.restart();repaint();}
        public void paint(Graphics gg){if(fase>=1||getWidth()==0||getHeight()==0){super.paint(gg);return;}Graphics2D g=(Graphics2D)gg.create();float t=1-(1-fase)*(1-fase);g.setComposite(AlphaComposite.SrcOver.derive(.35f+.65f*t));super.paint(g);g.dispose();}
    }
    private JPanel pagina(String titulo){JPanel p=new JPanel(new BorderLayout(0,8));p.setOpaque(false);JLabel l=label(titulo,32);l.setBorder(new EmptyBorder(4,4,4,4));p.add(l,BorderLayout.NORTH);return p;}
    private JPanel biblioteca(){JPanel p=pagina("recent / biblioteca musical");tabela.setRowHeight(27);tabela.setFont(fonte(14));tabela.setOpaque(false);tabela.setShowGrid(false);tabela.setIntercellSpacing(new Dimension(0,0));tabela.setDefaultRenderer(Object.class,new javax.swing.table.DefaultTableCellRenderer(){public Component getTableCellRendererComponent(JTable table,Object v,boolean selected,boolean focus,int row,int col){super.getTableCellRendererComponent(table,v,selected,false,row,col);setOpaque(selected);setBorder(new EmptyBorder(0,9,0,7));return this;}});tabela.setForeground(INK);tabela.setGridColor(new Color(195,207,209));tabela.getTableHeader().setFont(fonte(14));tabela.getTableHeader().setOpaque(false);tabela.getTableHeader().setBackground(new Color(174,192,196));tabela.getTableHeader().setDefaultRenderer(new javax.swing.table.DefaultTableCellRenderer(){public Component getTableCellRendererComponent(JTable table,Object v,boolean selected,boolean focus,int row,int col){super.getTableCellRendererComponent(table,v,false,false,row,col);setOpaque(false);setForeground(INK);setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0,0,1,0,new Color(95,120,128,95)),new EmptyBorder(5,9,6,5)));return this;}});tabela.setSelectionBackground(new Color(108,146,156));tabela.setSelectionForeground(Color.WHITE);tabela.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);tabela.getColumnModel().getColumn(0).setPreferredWidth(48);tabela.getColumnModel().getColumn(1).setPreferredWidth(150);tabela.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&tabela.getSelectedRow()>=0){int c=(Integer)modelo.getValueAt(tabela.getSelectedRow(),0);codigo.setText(""+c);Musica m=dados.get(c);if(m!=null)selecao.setText(m.detalhes());}});p.add(rolagem(tabela));return p;}
    private JPanel aba(PainelArvore p,String titulo,String legenda,JLabel altura){JPanel a=pagina(titulo);JPanel centro=new JPanel(new BorderLayout());centro.setOpaque(false);JPanel info=new JPanel(new FlowLayout(FlowLayout.LEFT,12,4));info.setOpaque(false);info.add(label("altura (arestas)",13));info.add(altura);info.add(label(legenda,12));centro.add(info,BorderLayout.NORTH);JScrollPane s=rolagem(p);centro.add(s);a.add(centro);return a;}
    private JPanel kd(){JPanel p=pagina("k-D / exemplo conceitual");JTextArea t=new JTextArea("Cada música pode ser um ponto (x = ano - 1990, y = duração em dezenas de segundos).\nA cada nível alternamos o eixo. Escolher a mediana produz uma árvore inicialmente balanceada.\n\nExemplo estático: 21 pontos fictícios\nRaiz: (11, 10) — eixo x\n    E: (5, 11) — eixo y\n        E: (6, 5) — eixo x\n            E: (1, 8) — eixo y\n                E: (3, 3) — eixo x\n            D: (10, 7) — eixo y\n                E: (8, 1) — eixo x\n        D: (7, 17) — eixo x\n            E: (4, 19) — eixo y\n                E: (2, 15) — eixo x\n            D: (9, 13) — eixo y\n    D: (19, 14) — eixo y\n        E: (16, 2) — eixo x\n            E: (15, 9) — eixo y\n                E: (13, 4) — eixo x\n            D: (20, 12) — eixo y\n                E: (18, 6) — eixo x\n        D: (17, 20) — eixo x\n            E: (12, 21) — eixo y\n                E: (14, 16) — eixo x\n            D: (21, 18) — eixo y\n\nBusca por (17,20): (11,10) → (19,14) → (17,20).\nPares idênticos são rejeitados; empates no eixo usam a outra coordenada.\nNão há implementação de k-D, conforme o enunciado.");t.setEditable(false);t.setLineWrap(true);t.setWrapStyleWord(true);t.setFont(fonte(17));t.setOpaque(false);t.setForeground(INK);t.setBorder(new EmptyBorder(18,18,18,18));p.add(rolagem(t));return p;}
    private void iniciar(){rb=new RubroNegra();a234=new Arvore234();dados.clear();for(int i=0;i<INICIAIS.length;i++){int c=INICIAIS[i],j=i%6;rb.inserir(c);a234.inserir(c);dados.put(c,new Musica(TITULOS[i],ARTISTAS[j],ALBUNS[j],GENEROS[j],2005+i%6,160+i*7));}codigo.setText("");selecao.setText("Selecione uma faixa ou informe seu código.");log.setText("DEMO / 31 músicas fictícias carregadas.\n");atualizar("Biblioteca pronta.",Collections.emptyList(),Collections.emptyList());}
    private Musica formulario(int c){JTextField t=new JTextField(),a=new JTextField(),al=new JTextField(),g=new JTextField(),y=new JTextField("2010"),s=new JTextField("210");JPanel f=new JPanel(new GridLayout(0,2,8,8));String[] nomes={"Título","Artista","Álbum","Gênero","Ano","Duração (segundos)"};JTextField[] campos={t,a,al,g,y,s};for(int i=0;i<nomes.length;i++){f.add(label(nomes[i],15));campos[i].setFont(fonte(15));f.add(campos[i]);}while(JOptionPane.showConfirmDialog(this,f,"Cadastrar música #"+c,JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){try{int ano=Integer.parseInt(y.getText().trim()),seg=Integer.parseInt(s.getText().trim());if(ano<1||ano>9999||seg<=0||t.getText().isBlank()||a.getText().isBlank()||al.getText().isBlank()||g.getText().isBlank())throw new IllegalArgumentException();return new Musica(t.getText().trim(),a.getText().trim(),al.getText().trim(),g.getText().trim(),ano,seg);}catch(IllegalArgumentException ex){JOptionPane.showMessageDialog(this,"Preencha todos os campos e informe ano e duração válidos.");}}return null;}
    private void operar(int op){int c;try{c=Integer.parseInt(codigo.getText().trim());if(c<=0)throw new NumberFormatException();}catch(NumberFormatException ex){resumo.setText("Informe um código inteiro positivo.");return;}List<NoVisual> p=Collections.emptyList(),q=Collections.emptyList();String msg;
        if(op==3){p=rb.caminhoBusca(c);q=a234.caminhoBusca(c);boolean x=rb.buscar(c),y=a234.buscar(c);if(x!=y||x!=dados.containsKey(c))throw new IllegalStateException("Índices divergentes");msg=x?"Encontrado #"+c:"Não encontrado #"+c;selecao.setText(x?dados.get(c).detalhes():"Nenhuma faixa com esse código.");log.append("\nBUSCA #"+c+" | RB: "+p.size()+" nó(s) | 2-3-4: "+q.size()+" nó(s)\n");}
        else{Musica m=null;if(op==1&&!rb.buscar(c)){m=formulario(c);if(m==null)return;}boolean x=op==1?rb.inserir(c):rb.excluir(c),y=op==1?a234.inserir(c):a234.excluir(c);if(x!=y)throw new IllegalStateException("Índices divergentes");if(x){if(op==1)dados.put(c,m);else dados.remove(c);}msg=op==1?(x?"Cadastrado #":"Duplicata recusada #")+c:(x?"Excluído #":"Código inexistente #")+c;selecao.setText(op==1&&x?m.detalhes():msg);log.append("\n"+msg+"\nRB: "+eventos(rb.eventos())+"\n2-3-4: "+eventos(a234.eventos())+"\n");}
        atualizar(msg,p,q);if(op==3)visitas.setText("Nós visitados: rubro-negra "+p.size()+"  /  2-3-4 "+q.size());}
    private String eventos(List<String> e){return e.isEmpty()?"Sem ajustes registrados":String.join("; ",e);}
    private void atualizar(String msg,List<NoVisual> p,List<NoVisual> q){if(!rb.valida()||!a234.valida()||!rb.emOrdem().equals(a234.emOrdem())||!dados.keySet().equals(new HashSet<>(rb.emOrdem())))throw new IllegalStateException("Falha de integridade");NoVisual r=rb.visual(),a=a234.visual();painelRB.atualizar(r,p);painel234.atualizar(a,q);total.setText(""+rb.tamanho());alturaRB.setText(""+(r==null?-1:r.altura()));altura234.setText(""+(a==null?-1:a.altura()));estado.setText("Integridade OK  /  índices sincronizados  /  dados em memória");resumo.setText(msg);visitas.setText("Nós visitados na busca: —");log.setCaretPosition(log.getDocument().getLength());modelo.setRowCount(0);for(int c:rb.emOrdem()){Musica m=dados.get(c);modelo.addRow(new Object[]{c,m.titulo,m.artista,m.album,m.genero,m.ano,m.duracao()});}capas.removeAll();int n=0;for(int c:rb.emOrdem()){if(n==5)break;Musica m=dados.get(c);final int chave=c;JPanel tile=new JPanel(new BorderLayout(0,3));tile.setOpaque(false);tile.setBorder(new EmptyBorder(0,0,0,0));Cover cover=new Cover(m.album,n++);tile.add(cover);JLabel l=label(m.titulo,13);l.setHorizontalAlignment(SwingConstants.CENTER);l.setToolTipText(m.detalhes());tile.add(l,BorderLayout.SOUTH);tile.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));java.awt.event.MouseAdapter clique=new java.awt.event.MouseAdapter(){public void mouseClicked(java.awt.event.MouseEvent e){codigo.setText(""+chave);operar(3);}};tile.addMouseListener(clique);cover.addMouseListener(clique);l.addMouseListener(clique);capas.add(tile);}capas.revalidate();capas.repaint();}
    private static class Gradiente extends JPanel{final Color a,b;Gradiente(Color a,Color b){this.a=a;this.b=b;setOpaque(false);}protected void paintComponent(Graphics g){Graphics2D x=(Graphics2D)g.create();x.setPaint(new GradientPaint(0,0,a,getWidth(),getHeight(),b));x.fillRect(0,0,getWidth(),getHeight());x.dispose();super.paintComponent(g);}}
    private static class Cover extends JPanel{final String album;final int estilo;float hover; final javax.swing.Timer animacao; Cover(String a,int e){album=a;estilo=e;setOpaque(false);animacao=new javax.swing.Timer(16,ev->{float alvo=getMousePosition()!=null?1:0;hover+=(alvo-hover)*.2f;repaint();if(Math.abs(alvo-hover)<.01f){hover=alvo;((javax.swing.Timer)ev.getSource()).stop();}});addMouseListener(new java.awt.event.MouseAdapter(){public void mouseEntered(java.awt.event.MouseEvent e){animacao.start();}public void mouseExited(java.awt.event.MouseEvent e){animacao.start();}});}protected void paintComponent(Graphics gg){Graphics2D g=(Graphics2D)gg.create();int w=getWidth(),h=getHeight();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);Color[] cores={new Color(52,88,100),new Color(102,80,103),new Color(43,66,82),new Color(107,117,105),new Color(90,84,77),new Color(44,96,101)};g.setPaint(new GradientPaint(0,0,cores[estilo],w,h,new Color(17,29,37)));g.fillRect(0,0,w,h);g.setColor(new Color(255,255,255,(int)(hover*38)));g.fillRect(0,0,w,h);g.setColor(new Color(220,238,238,100));for(int i=0;i<5;i++){if(estilo%2==0)g.draw(new Ellipse2D.Double(w*.2-i*5,h*.1+i*5,w*.6+i*10,h*.65-i*5));else g.drawLine(0,h*i/5,w,h-h*i/5);}g.setColor(Color.WHITE);g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,RenderingHints.VALUE_TEXT_ANTIALIAS_ON);g.setFont(fonte(13));FontMetrics fm=g.getFontMetrics();g.drawString(album,Math.max(3,(w-fm.stringWidth(album))/2),h-8);g.dispose();}}
